import { supabase } from '../../config/supabase.js';
import { sendError, mapDbError, sendPage } from '../../utils/respond.js';

export const createProduct = async (req, res) => {
    try {
        // 🔒 IDENTITY (Phase 4 Block V-A). `seller_id` was a body field on an
        // unauthenticated route, so anyone could publish a listing under any
        // student's name — with that student's campus stamped on it, their face
        // on the card, and their inbox receiving the buyers.
        //
        // The seller is the token holder. A `seller_id` in the body is ignored
        // in silence: both clients still send one today, and rejecting it would
        // only tell an attacker the parameter used to work.
        const seller_id = req.user.id;
        const { title, description, price, category, location, condition } = req.body;
        const files = req.files;

        if (!files || files.length === 0) {
            return res.status(400).json({ error: 'At least one image is required.' });
        }
        if (!title || !price || !category) {
            return res.status(400).json({ error: 'Title, price, and category are required.' });
        }

        // 1. Securely fetch the user's university_id to enforce multi-tenant
        // isolation. This is now the AUTHENTICATED seller's row: it used to be
        // whichever id the body claimed, so the campus stamped on the listing
        // was chosen by the caller as surely as the seller was.
        const { data: user, error: userError } = await supabase
            .from('users')
            .select('university_id')
            .eq('id', seller_id)
            .single();

        if (userError || !user) throw new Error('Seller not found.');
        const university_id = user.university_id;

        // 2. Upload multiple images to Supabase 'products' bucket
        const imageUrls = [];
        for (const file of files) {
            const fileExt = file.originalname.split('.').pop();
            // Create a unique filename: sellerId-timestamp-randomString.ext
            const fileName = `${seller_id}-${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;

            const { error: uploadError } = await supabase.storage
                .from('products')
                .upload(fileName, file.buffer, {
                    contentType: file.mimetype,
                    upsert: false
                });

            if (uploadError) throw uploadError;

            // Get public URL
            const { data: { publicUrl } } = supabase.storage
                .from('products')
                .getPublicUrl(fileName);

            imageUrls.push(publicUrl);
        }

        // 3. Insert the new product into the database
        const { data: product, error: insertError } = await supabase
            .from('products')
            .insert([{
                seller_id,
                university_id,
                title,
                description,
                price: Number(price),
                category,
                location,  
                condition, 
                image_urls: imageUrls,
                status: 'available'
            }])
            .select()
            .single();

        if (insertError) throw insertError;

        res.status(201).json({
            message: 'Product listed successfully!',
            product
        });

    } catch (error) {
        console.error('Create Product Error:', error);
        res.status(500).json({ error: 'Failed to create product listing.' });
    }
};

export const updateProduct = async (req, res) => {
    try {
        const { id } = req.params;

        // 🔒 OWNERSHIP (plan §1.6 Bug 1 / CURRENT_STATE audit).
        //
        // This handler used to take `id` straight from the URL and UPDATE on it
        // with no actor at all — anyone who knew a listing's uuid could rewrite
        // its title, price and status on any campus.
        //
        // The owner is `req.user.id` from the Bearer token verified by
        // requireAuth, and nothing else. There is deliberately no seller_id in
        // the body to compare against: a caller-supplied one would be exactly
        // the hole this closes.
        const { data: existing, error: lookupError } = await supabase
            .from('products')
            .select('seller_id')
            .eq('id', id)
            .maybeSingle();

        // maybeSingle, not single: "no such listing" is a 404, not a 500.
        if (lookupError) {
            console.error('Update Product Error (ownership lookup):', lookupError);
            return sendError(res, 500, 'INTERNAL_ERROR', {
                message: 'Failed to update product.',
            });
        }

        if (!existing) {
            return sendError(res, 404, 'NOT_FOUND', {
                message: 'That listing no longer exists.',
            });
        }

        if (existing.seller_id !== req.user.id) {
            return sendError(res, 403, 'FORBIDDEN', {
                message: 'You can only edit your own listings.',
            });
        }

        // 🩹 PARTIAL UPDATE (plan §1.6 Bug 2).
        //
        // This payload used to be built unconditionally from seven destructured
        // body fields. `JSON.stringify` drops the `undefined` ones on its own, so
        // six of them were harmless — but `price` went through `Number(price)`
        // first, and `Number(undefined)` is `NaN`, which serializes to `null`.
        // `products.price` is NOT NULL, so every body without a price hit 23502
        // and the seller got a generic 500. A title-only edit was impossible.
        //
        // The payload is now built from the keys the caller actually SENT.
        // Presence is tested with hasOwnProperty, not truthiness: `description: ''`
        // and `price: 0` are legitimate edits and must survive.
        const UPDATABLE = ['title', 'description', 'price', 'category', 'location', 'condition', 'status'];
        const sent = (field) => Object.prototype.hasOwnProperty.call(req.body, field);

        const updates = {};
        for (const field of UPDATABLE) {
            if (sent(field)) updates[field] = req.body[field];
        }

        // Price is the only field that is coerced, so it is the only one that can
        // become NaN. Validate before it reaches the column rather than letting
        // Postgres reject it as an opaque 500. `null`, `''` and booleans are
        // rejected explicitly: `Number()` maps all three onto a finite number.
        if (sent('price')) {
            const raw = req.body.price;
            const parsed = (raw === null || raw === '' || typeof raw === 'boolean')
                ? NaN
                : Number(raw);

            if (!Number.isFinite(parsed) || parsed < 0) {
                return sendError(res, 400, 'INVALID_PRICE', {
                    message: 'Price must be a number greater than or equal to 0.',
                });
            }
            updates.price = parsed;
        }

        // An UPDATE with no columns is a PostgREST error, not a no-op — refuse it
        // here so the caller gets a code instead of a leaked driver message.
        if (Object.keys(updates).length === 0) {
            return sendError(res, 400, 'MISSING_FIELDS', {
                message: 'Send at least one field to update.',
            });
        }

        // Update the product in the database
        const { data, error } = await supabase
            .from('products')
            .update(updates)
            .eq('id', id)
            .select()
            .single();

        if (error) throw error;

        res.status(200).json({
            message: 'Product updated successfully',
            product: data
        });
    } catch (error) {
        console.error('Update Product Error:', error);

        // A constraint violation is the caller's input, not our outage. Route the
        // two codes `mapDbError` recognises through it so they surface as 400s;
        // anything else keeps the documented INTERNAL_ERROR envelope.
        if (error?.code === '23505' || error?.code === '23503') {
            return mapDbError(res, error);
        }

        return sendError(res, 500, 'INTERNAL_ERROR', {
            message: 'Failed to update product.',
        });
    }
};

export const deleteProduct = async (req, res) => {
    try {
        const { id } = req.params;

        // 🔒 OWNERSHIP (plan §1.6 Bug 1). Same hole as updateProduct, same fix,
        // and worse in effect: an unauthenticated DELETE on a known uuid
        // destroyed any listing on any campus, cascading to its comments,
        // likes and saves.
        const { data: existing, error: lookupError } = await supabase
            .from('products')
            .select('seller_id')
            .eq('id', id)
            .maybeSingle();

        if (lookupError) {
            console.error('Delete Product Error (ownership lookup):', lookupError);
            return sendError(res, 500, 'INTERNAL_ERROR', {
                message: 'Failed to delete product.',
            });
        }

        if (!existing) {
            return sendError(res, 404, 'NOT_FOUND', {
                message: 'That listing no longer exists.',
            });
        }

        if (existing.seller_id !== req.user.id) {
            return sendError(res, 403, 'FORBIDDEN', {
                message: 'You can only delete your own listings.',
            });
        }

        // Delete the product from the database
        // Note: For a production app, you might also want to delete the images from the Supabase storage bucket here to save space.
        const { error } = await supabase
            .from('products')
            .delete()
            .eq('id', id);

        if (error) throw error;

        res.status(200).json({ message: 'Product deleted successfully' });
    } catch (error) {
        console.error('Delete Product Error:', error);
        return sendError(res, 500, 'INTERNAL_ERROR', {
            message: 'Failed to delete product.',
        });
    }
};

// ═══════════════════════════════════════════════════════════════════════════
// PAGINATION — Phase 4 Block N-B (Neeraj, in Vishwajeet's module by agreement;
// see the ownership-loan entry in docs/CHANGELOG.md). READ HANDLERS ONLY.
// Nothing below this banner is used by a write handler.
//
// Cursors, never OFFSET. `OFFSET 100000` makes Postgres discard 100,000 rows
// before returning anything, and rows shift under the reader between pages —
// on a feed ordered by `created_at DESC`, one new listing between two requests
// silently re-serves a row the client already has.
// ═══════════════════════════════════════════════════════════════════════════

const PAGE_LIMIT_DEFAULT = 20;
const PAGE_LIMIT_MAX = 50;

/**
 * Anchored uuid, no character class that can match a comma, parenthesis or dot.
 * Same regex and same reason as `messages.controller.js` — the comment cursor's
 * id half is interpolated into an `.or()` filter EXPRESSION, which PostgREST
 * parses rather than treats as a value. Validate before it reaches the string;
 * once concatenated there is nothing left to escape with.
 */
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Cap first, then floor, exactly as `user.controller.js -> searchUsers` does.
 * `limit=abc` is NaN and falls back to the default; `limit=0` and `limit=-1`
 * floor to 1; `limit=100000` caps to 50. An uncapped limit is a denial of
 * service (plan §0.5.4), so the cap is not advisory.
 */
function parsePageLimit(raw) {
    const requested = Number.parseInt(raw, 10);
    return Number.isNaN(requested)
        ? PAGE_LIMIT_DEFAULT
        : Math.min(Math.max(requested, 1), PAGE_LIMIT_MAX);
}

/**
 * A cursor is absent unless it is a non-empty string. `?cursor=` (empty) and
 * `?cursor=a&cursor=b` (an array) both mean "first page" rather than an error:
 * they are far more likely to be a client building a URL badly than an attack,
 * and page one is the answer that cannot be wrong.
 */
function readCursorParam(raw) {
    return typeof raw === 'string' && raw.length > 0 ? raw : null;
}

/** Parseable as an instant. Guards `.lt()` against a 22007 cast error -> 500. */
function isTimestamp(value) {
    return typeof value === 'string' && !Number.isNaN(Date.parse(value));
}

/**
 * The comment cursor is COMPOUND: `created_at` alone is not unique here.
 * `seedLocal.js` bulk-inserts comments, so three rows sharing a timestamp to
 * the microsecond is the normal case, not a race — and a timestamp-only cursor
 * on a tie either drops the rest of the tied group or serves it twice forever.
 * `(created_at, id)` is unique because `id` is the primary key.
 *
 * It is encoded so the client never assembles one. base64url, not plain
 * base64: the payload's `+00:00` offset and the `=` padding both need escaping
 * in a query string, and a client that forgets is a silent wrong answer.
 */
function encodeCommentCursor(comment) {
    return Buffer.from(`${comment.created_at}|${comment.id}`, 'utf8').toString('base64url');
}

/**
 * Returns `{ created_at, id }`, or `null` for anything that is not a cursor
 * this endpoint issued. `Buffer.from(..., 'base64url')` does not throw on junk
 * — it drops the characters it cannot read — so the decode is not the check.
 * Validating both halves afterwards is. A `null` here must become a 400
 * INVALID_FORMAT, never an interpolation into the filter string below.
 */
function decodeCommentCursor(raw) {
    let decoded;
    try {
        decoded = Buffer.from(raw, 'base64url').toString('utf8');
    } catch {
        return null;
    }

    const parts = decoded.split('|');
    if (parts.length !== 2) return null;

    const [created_at, id] = parts;
    if (!isTimestamp(created_at)) return null;
    if (!UUID_RE.test(id)) return null;

    return { created_at, id };
}

/**
 * `sendPage()` in respond.js is FROZEN and owns the whole response — it calls
 * `res.json()` itself. The comments list is nested inside the product payload,
 * so it cannot be sent through it. This reproduces sendPage's rule exactly
 * (`items.length === limit ? last[cursorField] : null`) for that one nested
 * case, and nothing else. It is deliberately not a second envelope: the shape
 * it feeds is the same `{ items, next_cursor }`.
 *
 * If respond.js ever gains a non-terminating `buildPage()`, delete this and
 * call that. Do not grow it — a new list endpoint uses `sendPage`.
 */
function nextCursorOrNull(rows, limit, encode) {
    return rows.length === limit ? encode(rows[rows.length - 1]) : null;
}

/** The comment projection, shared by the two reads that return comments. */
const COMMENT_SELECT = `
                    id,
                    content,
                    created_at,
                    upvotes,
                    downvotes,
                    parent_comment_id,
                    user:users!comments_user_id_fkey(id, full_name, avatar_url)
`;

export const getProducts = async (req, res) => {
    try {
        const { university_id } = req.query;

        // 🔒 VIEWER (Phase 4 Block V-A follow-up). Was `req.query.user_id` — the
        // caller named whose like/save flags came back, so anyone could pass any
        // uuid and read a third party's `is_liked` / `is_saved` across a whole
        // campus feed. The viewer comes from the token now, and a `user_id` in
        // the query string is ignored in silence: five client call sites across
        // web and mobile still send it, and rejecting it would break them for no
        // security gain — exactly the treatment `toggleLikeProduct` gives a
        // `user_id` in the body.
        //
        // optionalAuth, NOT requireAuth. Anonymous browsing of the marketplace
        // is a deliberate feature, so `req.user` is `null` for a signed-out
        // caller and `?.` is load-bearing rather than defensive. An anonymous
        // viewer gets the listings with no flags attached, which is correct —
        // see the `if (viewerId)` guard below.
        const viewerId = req.user?.id;

        if (!university_id) {
            return res.status(400).json({ error: 'university_id query parameter is required.' });
        }

        // 📄 PAGINATION (Phase 4 Block N-B). Both params are OPTIONAL and both
        // clients still call this with neither — they keep working, they just
        // receive the newest 20 listings instead of the whole campus feed.
        //
        // The cursor is a bare `created_at` timestamp, not the compound cursor
        // the comments list uses. Listings are created one at a time by a human
        // pressing a button, so two sharing a timestamp to the microsecond is
        // not a realistic case; comments are bulk-inserted by seed scripts and
        // are, which is why the two endpoints differ.
        const limit = parsePageLimit(req.query.limit);
        const cursor = readCursorParam(req.query.cursor);

        // A cursor that is not a timestamp would reach `.lt()` and make Postgres
        // raise 22007, which the catch below would report as a 500 — a server
        // error for what is plainly a bad request. Reject it here instead.
        if (cursor !== null && !isTimestamp(cursor)) {
            return sendError(res, 400, 'INVALID_FORMAT', {
                message: 'cursor must be the next_cursor value from a previous response.',
            });
        }

        // 1. Fetch products for the requested campus
        let query = supabase
            .from('products')
            .select(`
                *,
                seller:users!seller_id(id, full_name, avatar_url)
            `)
            .eq('university_id', university_id)
            .eq('status', 'available')
            .order('created_at', { ascending: false })
            .limit(limit);

        // Strictly less-than, so the row the cursor names is not served twice.
        // `.lt()` takes a VALUE, not a filter expression — there is no string
        // for a crafted cursor to escape out of here.
        if (cursor !== null) query = query.lt('created_at', cursor);

        const { data: products, error } = await query;

        if (error) throw error;

        // 2. If a user is logged in, attach their specific 'liked' and 'saved' statuses
        if (viewerId && products.length > 0) {
            const productIds = products.map(p => p.id);
            
            // Run both queries in parallel for performance
            const [likesRes, savesRes] = await Promise.all([
                supabase.from('product_likes').select('product_id').eq('user_id', viewerId).in('product_id', productIds),
                supabase.from('product_saves').select('product_id').eq('user_id', viewerId).in('product_id', productIds)
            ]);

            // Convert to Sets for instant O(1) lookups
            const likedSet = new Set(likesRes.data?.map(l => l.product_id) || []);
            const savedSet = new Set(savesRes.data?.map(s => s.product_id) || []);

            products.forEach(p => {
                p.is_liked = likedSet.has(p.id);
                p.is_saved = savedSet.has(p.id);
            });
        }

        // 📄 `{ items, next_cursor }` via the frozen sendPage() — API.md "The list
        // envelope". This replaces `{ products }`: the envelope key changed, the
        // shape of an individual listing did not. `next_cursor` is null on the
        // last page and is the ONLY end-of-list signal — a short page is not one,
        // because a page can be exactly `limit` rows with nothing behind it.
        return sendPage(res, products, 'created_at', limit);
    } catch (error) {
        console.error('Get Products Error:', error);
        res.status(500).json({ error: 'Failed to fetch marketplace feed.' });
    }
};

export const getProductById = async (req, res) => {
    try {
        const { id } = req.params;

        // 🔒 VIEWER (Phase 4 Block V-A follow-up). Same fix as `getProducts`
        // above, and this handler leaked one field more: `comment_votes` told
        // the caller how any named student had voted on every comment on the
        // listing. Viewer comes from the token; a `user_id` in the query string
        // is ignored in silence, because both clients still send one.
        //
        // optionalAuth, so a signed-out caller reads the listing with no flags.
        const viewerId = req.user?.id;

        // 📄 PAGINATION (Phase 4 Block N-B). `limit` and `cursor` are optional
        // and apply to the COMMENTS list only — the listing itself is one row.
        const limit = parsePageLimit(req.query.limit);
        const rawCursor = readCursorParam(req.query.cursor);

        // An undecodable cursor is a 400, not a 500, and above all not a string
        // spliced into the `.or()` expression below. Anything that is not a
        // cursor this endpoint issued stops here.
        const cursor = rawCursor === null ? null : decodeCommentCursor(rawCursor);
        if (rawCursor !== null && cursor === null) {
            return sendError(res, 400, 'INVALID_FORMAT', {
                message: 'cursor must be the next_cursor value from a previous response.',
            });
        }

        // 1. Fetch Product + Seller, and the page of comments, in parallel.
        //
        // Comments used to ride along as an embedded `comments(...)` join on the
        // product select. They are their own query now because the compound
        // cursor has to filter and order them independently of the product row.
        // Splitting it costs no extra round trip — the two run together.
        //
        // ── WHAT IS PAGINATED, AND WHY IT IS NOT THE FLAT LIST ──────────────
        // `limit` counts TOP-LEVEL comments. Every reply belonging to the
        // parents on this page is returned with them, however many that is, so
        // a page of 20 can carry more than 20 items.
        //
        // Both clients thread client-side and identically:
        //   top level -> comments.filter(c => !c.parent_comment_id)
        //   replies   -> comments.filter(c => c.parent_comment_id === parentId)
        // (frontend ProductDetail.jsx:378-380, mobile CommentThread.tsx:78-80.)
        //
        // Paginating the flat list would therefore DELETE replies from the UI
        // rather than defer them: a reply whose parent sits on a later page
        // fails the first filter (it has a parent) and matches no visible parent
        // in the second, so neither client renders it anywhere and nothing tells
        // the reader it exists. Paging by parent makes an orphan impossible —
        // a reply is on the same page as its parent or on neither.
        //
        // Depth is NOT capped. `NESTED_REPLY_NOT_ALLOWED` exists in respond.js's
        // list of raise-able names but no migration defines a trigger that
        // raises it, and `addComment` does not check either — API.md says so
        // outright. So this walks descendants rather than assuming two levels:
        // a depth-3 reply is rare and no client renders it, but the endpoint
        // returns it today and dropping it silently is not this block's call.
        const topLevelQuery = (() => {
            let q = supabase
                .from('comments')
                .select(COMMENT_SELECT)
                .eq('product_id', id)
                .is('parent_comment_id', null)
                .order('created_at', { ascending: false })
                .order('id', { ascending: false })
                .limit(limit);

            // Keyset, not OFFSET: "older than the cursor row, or the same
            // instant with a lower id". The second leg is what makes a tie
            // total — without it, three comments sharing a microsecond either
            // repeat forever or vanish at the page boundary. Both values were
            // validated by decodeCommentCursor; the timestamp is double-quoted
            // so its `+00:00` offset cannot be read as filter syntax.
            if (cursor !== null) {
                q = q.or(
                    `created_at.lt."${cursor.created_at}",` +
                    `and(created_at.eq."${cursor.created_at}",id.lt.${cursor.id})`
                );
            }
            return q;
        })();

        const [productRes, topLevelRes] = await Promise.all([
            supabase
                .from('products')
                .select(`
                    *,
                    seller:users!seller_id(id, full_name, avatar_url, qualification, year_of_study)
                `)
                .eq('id', id)
                .single(),
            topLevelQuery,
        ]);

        const { data: product, error } = productRes;
        if (error) throw error;
        if (topLevelRes.error) throw topLevelRes.error;

        const topLevel = topLevelRes.data ?? [];

        // Every DESCENDANT of the parents on this page, level by level.
        // Unpaginated on purpose — see the orphan note above.
        //
        // Two round trips in the ordinary case: one that returns the replies,
        // one that comes back empty and ends the walk. `REPLY_DEPTH_CAP` stops
        // a pathological thread from turning one request into an unbounded
        // number of queries; `seen` makes a repeat impossible even if the data
        // is somehow cyclic. Hitting the cap truncates the deepest replies
        // rather than failing the listing — the alternative is a 500 on a page
        // that is 99% renderable.
        const REPLY_DEPTH_CAP = 10;
        const replies = [];
        const seen = new Set();
        let frontier = topLevel.map(c => c.id);

        for (let depth = 0; depth < REPLY_DEPTH_CAP && frontier.length > 0; depth++) {
            const { data: replyRows, error: replyError } = await supabase
                .from('comments')
                .select(COMMENT_SELECT)
                .in('parent_comment_id', frontier)
                .order('created_at', { ascending: false })
                .order('id', { ascending: false });

            if (replyError) throw replyError;

            const fresh = (replyRows ?? []).filter(c => !seen.has(c.id));
            fresh.forEach(c => seen.add(c.id));
            replies.push(...fresh);
            frontier = fresh.map(c => c.id);
        }

        // One flat array, `created_at` descending, exactly the shape and order
        // the clients already receive — a reply can still sort above its parent,
        // which is what they render today. Only the SET of rows is narrower.
        const comments = [...topLevel, ...replies].sort((x, y) => {
            if (x.created_at !== y.created_at) return x.created_at < y.created_at ? 1 : -1;
            return x.id < y.id ? 1 : -1;
        });

        // The cursor is derived from the last TOP-LEVEL row, because that is
        // what the limit counted and what the next page continues from.
        const commentsNextCursor = nextCursorOrNull(topLevel, limit, encodeCommentCursor);

        // 2. Fetch user's specific interaction states
        if (viewerId) {
            const [likesRes, savesRes, votesRes] = await Promise.all([
                supabase.from('product_likes').select('product_id').eq('user_id', viewerId).eq('product_id', id).single(),
                supabase.from('product_saves').select('product_id').eq('user_id', viewerId).eq('product_id', id).single(),
                // Only the comments actually on this page need a vote lookup.
                comments.length > 0
                    ? supabase.from('comment_votes').select('comment_id, vote_value').eq('user_id', viewerId).in('comment_id', comments.map(c => c.id))
                    : Promise.resolve({ data: [] })
            ]);

            product.is_liked = !!likesRes.data;
            product.is_saved = !!savesRes.data;

            const userVotes = {};
            if (votesRes.data) {
                votesRes.data.forEach(v => {
                    userVotes[v.comment_id] = v.vote_value;
                });
            }

            comments.forEach(c => {
                c.user_vote = userVotes[c.id] || 0;
            });
        }

        // 📄 The comments list is the standard `{ items, next_cursor }` envelope
        // from API.md, nested under `product`. `product.comments` was a bare
        // array until 15 Sep 2026; the individual comment shape is unchanged.
        product.comments = { items: comments, next_cursor: commentsNextCursor };

        // 3. Increment the view metric via the RPC
        await supabase.rpc('increment_product_views', { product_id: id });

        res.status(200).json({ product });
    } catch (error) {
        console.error('Get Product By ID Error:', error);
        res.status(500).json({ error: 'Failed to fetch product details.' });
    }
};


/**
 * Minimal, read-only product data for link previews (Open Graph cards).
 *
 * Deliberately NOT getProductById: that endpoint increments the view counter
 * and joins every comment, so using it here would inflate view counts on every
 * crawler hit and over-fetch badly for a card that shows four fields.
 */
export const getProductMeta = async (req, res) => {
    try {
        const { id } = req.params;

        const { data: product, error } = await supabase
            .from('products')
            .select(`
                id, title, description, price, condition, image_urls, status,
                seller:users!seller_id(full_name),
                university:universities!university_id(name)
            `)
            .eq('id', id)
            .single();

        if (error || !product) {
            return res.status(404).json({ error: 'Product not found.' });
        }

        // Cacheable: previews are crawled repeatedly and the data is public.
        res.set('Cache-Control', 'public, max-age=300, s-maxage=300');
        res.status(200).json({
            product: {
                id: product.id,
                title: product.title,
                description: product.description,
                price: product.price,
                condition: product.condition,
                status: product.status,
                image: product.image_urls?.[0] || null,
                seller_name: product.seller?.full_name || null,
                university_name: product.university?.name || null,
            },
        });
    } catch (error) {
        console.error('Get Product Meta Error:', error);
        res.status(500).json({ error: 'Failed to fetch product meta.' });
    }
};

/**
 * 🔒 Guard for every same-campus INTERACTION on a listing (plan §1.6 Bug 2).
 *
 * Yahora's product rule is **browse across campuses, interact only on your
 * own**. `getProducts` is deliberately cross-campus, so a student can see a
 * listing from another university — but liking or saving it was allowed too,
 * which turned a read-only browse into an interaction the rule forbids.
 *
 * Returns `null` when the caller may proceed. Otherwise it has already sent
 * the response, and the caller must return immediately.
 *
 * Both reads are independent, so they cost one round trip rather than two.
 */
async function blockCrossCampusInteraction(req, res, productId, label) {
    const [productRes, meRes] = await Promise.all([
        supabase.from('products').select('university_id').eq('id', productId).maybeSingle(),
        supabase.from('users').select('university_id').eq('id', req.user.id).maybeSingle(),
    ]);

    if (productRes.error || meRes.error) {
        console.error(`${label} Error (campus lookup):`, productRes.error || meRes.error);
        sendError(res, 500, 'INTERNAL_ERROR');
        return true;
    }

    if (!productRes.data) {
        sendError(res, 404, 'NOT_FOUND', { message: 'That listing no longer exists.' });
        return true;
    }

    if (!meRes.data) {
        sendError(res, 404, 'NOT_FOUND', { message: 'No profile exists for this account.' });
        return true;
    }

    const productCampus = productRes.data.university_id;
    const myCampus      = meRes.data.university_id;

    // A NULL on either side is treated as a mismatch, not as a pass. Products
    // always carry a campus, but `handle_new_user` (migration 005) creates a
    // user row with university_id NULL when the email domain is unknown — and
    // "I could not establish that you are on this campus" must fail closed.
    // No real student is affected: every account created through requestOtp
    // has a validated domain and therefore a campus.
    if (!productCampus || !myCampus || productCampus !== myCampus) {
        sendError(res, 403, 'CROSS_CAMPUS_INTERACTION_BLOCKED', {
            message: 'You can only interact with listings on your own campus.',
        });
        return true;
    }

    return false;
}

export const toggleLikeProduct = async (req, res) => {
    try {
        const { id: product_id } = req.params;

        // 🔒 IDENTITY. Was `req.body.user_id` — forgeable, so anyone could like
        // or unlike as any student. It comes from the verified token now, and a
        // `user_id` in the body is ignored in silence: rejecting it would only
        // tell an attacker the parameter used to work.
        const user_id = req.user.id;

        if (await blockCrossCampusInteraction(req, res, product_id, 'Toggle Like')) return;

        const { data: existingLike } = await supabase
            .from('product_likes')
            .select('*')
            .eq('user_id', user_id)
            .eq('product_id', product_id)
            .single();

        if (existingLike) {
            // Deleting the row will now AUTOMATICALLY fire the trigger and decrement the count!
            await supabase.from('product_likes').delete().match({ user_id, product_id });
            res.status(200).json({ message: 'Product unliked', is_liked: false });
        } else {
            // Inserting the row will now AUTOMATICALLY fire the trigger and increment the count!
            await supabase.from('product_likes').insert([{ user_id, product_id }]);
            res.status(200).json({ message: 'Product liked', is_liked: true });
        }
    } catch (error) {
        console.error('Toggle Like Error:', error);
        return sendError(res, 500, 'INTERNAL_ERROR', {
            message: 'Failed to toggle like status.',
        });
    }
};

export const toggleSaveProduct = async (req, res) => {
    try {
        const { id: product_id } = req.params;

        // 🔒 IDENTITY — same as toggleLikeProduct above.
        const user_id = req.user.id;

        if (await blockCrossCampusInteraction(req, res, product_id, 'Toggle Save')) return;

        const { data: existingSave } = await supabase
            .from('product_saves')
            .select('*')
            .eq('user_id', user_id)
            .eq('product_id', product_id)
            .single();

        if (existingSave) {
            await supabase.from('product_saves').delete().match({ user_id, product_id });
            res.status(200).json({ message: 'Product removed from wishlist', is_saved: false });
        } else {
            await supabase.from('product_saves').insert([{ user_id, product_id }]);
            res.status(200).json({ message: 'Product saved to wishlist', is_saved: true });
        }
    } catch (error) {
        console.error('Toggle Save Error:', error);
        return sendError(res, 500, 'INTERNAL_ERROR', {
            message: 'Failed to toggle save status.',
        });
    }
};


export const addComment = async (req, res) => {
    try {
        const { id: product_id } = req.params;

        // 🔒 IDENTITY (Phase 4 Block V-A). `user_id` came from the body on an
        // unauthenticated route, so any caller could put words under any
        // student's name and avatar on a public listing. Same treatment as
        // like/save: the actor is the token holder and a `user_id` in the body
        // is ignored in silence.
        const user_id = req.user.id;
        const { content, parent_comment_id } = req.body;

        const { data: user, error: userError } = await supabase
            .from('users')
            .select('university_id')
            .eq('id', user_id)
            .single();
        
        if (userError || !user) throw new Error('User not found.');

        // Insert and fetch back using the explicit join
        const { data: comment, error } = await supabase
            .from('comments')
            .insert([{
                product_id,
                user_id,
                university_id: user.university_id,
                content,
                parent_comment_id: parent_comment_id || null
            }])
            .select(`
                id, content, created_at, upvotes, downvotes, parent_comment_id,
                user:users!comments_user_id_fkey(id, full_name, avatar_url)
            `)
            .single();

        if (error) throw error;
        
        res.status(201).json({ message: 'Comment added successfully', comment });
    } catch (error) {
        console.error('Add Comment Error:', error);
        res.status(500).json({ error: 'Failed to post comment.' });
    }
};

export const toggleCommentVote = async (req, res) => {
    try {
        const { commentId } = req.params;

        // 🔒 IDENTITY (Phase 4 Block V-A). Was `req.body.user_id`, handed
        // straight to the RPC as `p_user_id` — the vote is stored per user, so a
        // forged id let one caller cast, flip and withdraw votes on behalf of
        // every student on campus. The actor is the token holder; a `user_id` in
        // the body is ignored in silence.
        const user_id = req.user.id;
        const { vote_value } = req.body; // Expects 1 (upvote) or -1 (downvote)

        if (![1, -1].includes(vote_value)) {
            return res.status(400).json({ error: 'Invalid vote value. Must be 1 or -1.' });
        }

        // Trigger the Smart RPC we built in Phase 1
        const { error } = await supabase.rpc('toggle_comment_vote', {
            p_comment_id: commentId,
            p_user_id: user_id,
            p_vote_value: vote_value
        });

        if (error) throw error;

        res.status(200).json({ message: 'Vote registered successfully' });
    } catch (error) {
        console.error('Toggle Comment Vote Error:', error);
        res.status(500).json({ error: 'Failed to register vote.' });
    }
};

/**
 * 🔒 Guard for the two status endpoints (Phase 4 Block V-A).
 *
 * The same ownership check `updateProduct` and `deleteProduct` already run,
 * factored out because /sold and /available need it identically. Status IS the
 * listing — marking someone else's item sold takes it out of the marketplace,
 * and marking it available again resurrects it and destroys its purchase
 * history — so these two need exactly the check the `PUT` has.
 *
 * Returns `true` when the response has already been sent and the caller must
 * return immediately; `false` when the caller owns the listing and may proceed.
 */
async function blockNonOwner(req, res, productId, label, failureMessage) {
    const { data: existing, error: lookupError } = await supabase
        .from('products')
        .select('seller_id')
        .eq('id', productId)
        .maybeSingle();

    // maybeSingle, not single: "no such listing" is a 404, not a 500.
    if (lookupError) {
        console.error(`${label} Error (ownership lookup):`, lookupError);
        sendError(res, 500, 'INTERNAL_ERROR', { message: failureMessage });
        return true;
    }

    if (!existing) {
        sendError(res, 404, 'NOT_FOUND', {
            message: 'That listing no longer exists.',
        });
        return true;
    }

    if (existing.seller_id !== req.user.id) {
        sendError(res, 403, 'FORBIDDEN', {
            message: 'You can only change the status of your own listings.',
        });
        return true;
    }

    return false;
}

export const markProductAsSold = async (req, res) => {
   try {
       const { id } = req.params;

       // `buyer_id` STAYS a body field. It names the other party to the sale,
       // not the actor, so it is a parameter rather than a claim of identity —
       // the seller is the one telling us who bought it. Only the actor moved
       // to the token.
       const { buyer_id } = req.body;

       // 🔒 OWNERSHIP (Phase 4 Block V-A). This route had no auth and no owner
       // check: any caller who knew a uuid could mark any listing on any campus
       // sold, which removes it from the marketplace and from every /public
       // profile. A competitor could clear a campus in an afternoon.
       if (await blockNonOwner(req, res, id, 'Mark Sold', 'Failed to mark product as sold.')) return;

       // 1. Update the product status to 'sold'
       const { data: product, error: updateError } = await supabase
           .from('products')
           .update({ status: 'sold' })
           .eq('id', id)
           .select()
           .single();

       if (updateError) throw updateError;

       // 2. If a buyer was selected from the platform, record the purchase for social proof
       if (buyer_id) {
           const { error: purchaseError } = await supabase
               .from('purchases')
               .insert([{
                   buyer_id: buyer_id,
                   product_id: id
               }]);

           if (purchaseError) console.error("Failed to insert purchase record:", purchaseError);
       }

       res.status(200).json({ message: 'Product marked as sold', product });
   } catch (error) {
       console.error('Mark Sold Error:', error);
       res.status(500).json({ error: 'Failed to mark product as sold.' });
   }
};

export const markProductAsAvailable = async (req, res) => {
   try {
       const { id } = req.params;

       // 🔒 OWNERSHIP (Phase 4 Block V-A). Same check as /sold, and the damage
       // here is not symmetric: step 2 below deletes EVERY `purchases` row for
       // the product, so an unauthenticated call destroyed purchase history
       // that nothing can reconstruct.
       if (await blockNonOwner(req, res, id, 'Mark Available', 'Failed to mark product as available.')) return;

       // 1. Update the product status back to 'available'
       const { data: product, error: updateError } = await supabase
           .from('products')
           .update({ status: 'available' })
           .eq('id', id)
           .select()
           .single();

       if (updateError) throw updateError;

       // 2. Remove the purchase record to undo the social proof
       const { error: purchaseError } = await supabase
           .from('purchases')
           .delete()
           .eq('product_id', id);

       if (purchaseError) console.error("Failed to delete purchase record:", purchaseError);

       res.status(200).json({ message: 'Product marked as available', product });
   } catch (error) {
       console.error('Mark Available Error:', error);
       res.status(500).json({ error: 'Failed to mark product as available.' });
   }
};


